"use strict";(self.webpackChunkbed_mega_textbook=self.webpackChunkbed_mega_textbook||[]).push([[1133],{1761(e,t,n){n.r(t),n.d(t,{assets:()=>h,contentTitle:()=>c,default:()=>d,frontMatter:()=>r,metadata:()=>i,toc:()=>l});const i=JSON.parse('{"id":"eed-313/unit-04/unit-teacher-notes","title":"Unit 4 teacher notes","description":"EED-313 Unit 4 tutor guidance: sequencing the four topics, the misconceptions to probe, managing the activities, and practicum links for community, care and accountability.","source":"@site/licence/eed-313/unit-04/unit-teacher-notes.mdx","sourceDirName":"eed-313/unit-04","slug":"/eed-313/unit-04/unit-teacher-notes","permalink":"/licence/eed-313/unit-04/unit-teacher-notes","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"title":"Unit 4 teacher notes","description":"EED-313 Unit 4 tutor guidance: sequencing the four topics, the misconceptions to probe, managing the activities, and practicum links for community, care and accountability.","course_code":"EED-313","unit_no":4,"clo_refs":["SLO:EED-313-4-6"],"blooms_summary":"Guidance for tutors sequencing Unit 4: how to move trainees from seeing care as permissiveness to seeing it as a management strategy; how to run the four topic activities; what misconceptions to probe; and how to design the practicum tasks so they produce usable evidence.","est_reading_minutes":6,"translation_status":"draft"},"sidebar":"licenceSidebar","previous":{"title":"Unit 4 assessment","permalink":"/licence/eed-313/unit-04/unit-assessment"},"next":{"title":"Course review","permalink":"/licence/eed-313/unit-05/"}}');var s=n(4848),o=n(8453),a=n(6606);const r={title:"Unit 4 teacher notes",description:"EED-313 Unit 4 tutor guidance: sequencing the four topics, the misconceptions to probe, managing the activities, and practicum links for community, care and accountability.",course_code:"EED-313",unit_no:4,clo_refs:["SLO:EED-313-4-6"],blooms_summary:"Guidance for tutors sequencing Unit 4: how to move trainees from seeing care as permissiveness to seeing it as a management strategy; how to run the four topic activities; what misconceptions to probe; and how to design the practicum tasks so they produce usable evidence.",est_reading_minutes:6,translation_status:"draft"},c="Unit 4 teacher notes",h={},l=[{value:"Sequencing note",id:"sequencing-note",level:2},{value:"Common misconceptions to probe",id:"common-misconceptions-to-probe",level:2},{value:"Managing the activities",id:"managing-the-activities",level:2},{value:"Practical work and practicum links",id:"practical-work-and-practicum-links",level:2},{value:"A note on the figures",id:"a-note-on-the-figures",level:2},{value:"Assessment note",id:"assessment-note",level:2}];function u(e){const t={h1:"h1",h2:"h2",header:"header",li:"li",ol:"ol",p:"p",strong:"strong",ul:"ul",...(0,o.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(a.A,{}),"\n",(0,s.jsx)(t.header,{children:(0,s.jsx)(t.h1,{id:"unit-4-teacher-notes",children:"Unit 4 teacher notes"})}),"\n",(0,s.jsx)(t.h2,{id:"sequencing-note",children:"Sequencing note"}),"\n",(0,s.jsx)(t.p,{children:"The four topics follow the logic of an expanding circle. Topic 4.1 asks what community means; Topic\n4.2 asks how to bring it into the classroom; Topic 4.3 asks what kind of relationships a caring\nclassroom is built on; Topic 4.4 asks what happens when those relationships are tested."}),"\n",(0,s.jsx)(t.p,{children:"A useful session order is to teach the topics in numerical order across the four weeks the guide\nallows (Weeks 12 to 15), using the first session of the unit to map the community circles around\nthe trainees' own practicum schools and the last to rehearse the integrative assessment. The unit\nis designed so that a tutor who needs to compress it can merge the activity time of Topics 4.1 and\n4.2 into a single community-mapping workshop without losing the conceptual spine."}),"\n",(0,s.jsx)(t.h2,{id:"common-misconceptions-to-probe",children:"Common misconceptions to probe"}),"\n",(0,s.jsx)(t.p,{children:"These are the misconceptions the unit names explicitly. Surface them early and return to them;\ntrainees often assent to the correct version in a discussion and then revert when they plan."}),"\n",(0,s.jsxs)(t.ol,{children:["\n",(0,s.jsxs)(t.li,{children:["\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:'"Community involvement means asking parents for money."'}),' This is the most persistent one.\nProbe it by asking: "If a parent gives money but never visits the school, is that involvement?"\nTrainees who equate community support with financial contribution will find the distinction\ncounter-intuitive. The figure in Topic 4.1 (participation vs involvement) is designed to make\nthe distinction visible; use it as a poster or handout.']}),"\n"]}),"\n",(0,s.jsxs)(t.li,{children:["\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:'"An ethic of care means never correcting a child."'}),' Probe it by asking: "If a pupil is about\nto make a dangerous mistake, does care mean letting them?" The answer is no, and the six-step\nmodel in Topic 4.4 is designed to show how correction and care coexist.']}),"\n"]}),"\n",(0,s.jsxs)(t.li,{children:["\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:'"A caring classroom has no consequences."'}),' Probe it by asking: "If a pupil hurts a classmate\nand nothing happens, is that caring - for whom?" The answer is that the hurt classmate deserves a\nresponse, and the six-step model shows what a caring consequence looks like.']}),"\n"]}),"\n"]}),"\n",(0,s.jsx)(t.h2,{id:"managing-the-activities",children:"Managing the activities"}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Topic 4.1 - Participation or involvement? (15 minutes)."})," This is a quick classification task.\nThe key teaching move is the debrief: ask trainees to identify the scenario where the boundary is\nunclear, and use it to make the point that the boundary is a matter of voice, not presence."]}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Topic 4.2 - Plan a community visit (25 minutes)."}),' The trap is that trainees produce a vague\ninvitation rather than a six-phase plan. The difference: a vague invitation says "come and talk";\na six-phase plan says what the need is, who the person is, what the first contact says, what the\nvisit looks like, how it is hosted, and what the follow-up is. The debrief question - "identify one\nmoment where the visit could become a performance" - is designed to catch this.']}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Topic 4.3 - Trace one incident twice (20 minutes)."}),' This is the most emotionally demanding\nactivity. The key teaching move is to make the comparison explicit: write the two traces side by\nside and ask, "What is the message to the class in each?" The divergence is usually at step 2: the\npunitive trace skips "check for harm" and goes straight to blame.']}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Topic 4.4 - Evaluate a response (20 minutes)."}),' The trap is that trainees evaluate the outcome\n(quiet class) rather than the process (relationship rebuilt). Push them back: "The class is quiet\nin both responses. What is different?" The answer is the relationship, and the six-step model is the\ntool for making it visible.']}),"\n",(0,s.jsx)(t.h2,{id:"practical-work-and-practicum-links",children:"Practical work and practicum links"}),"\n",(0,s.jsx)(t.p,{children:'Each topic carries a "Try this at your practicum school" task. The unit works best when the tutor\nsets these up explicitly before trainees leave for practicum and debriefs them when trainees\nreturn.'}),"\n",(0,s.jsxs)(t.ul,{children:["\n",(0,s.jsxs)(t.li,{children:["\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Topic 4.1 practicum task"})," (classify school-community interactions) produces a tally. Use it\nto open Topic 4.2: ask trainees which interactions are participation-only, and use their examples\nto motivate the six-phase model."]}),"\n"]}),"\n",(0,s.jsxs)(t.li,{children:["\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Topic 4.2 practicum task"})," (plan a community visit) produces a plan. Use it to make the point\nthat community involvement is a routine, not a one-off event."]}),"\n"]}),"\n",(0,s.jsxs)(t.li,{children:["\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Topic 4.3 practicum task"})," (note caring teacher moves) produces a list. Use it to make the\npoint that care is a set of practised routines, not a personality trait."]}),"\n"]}),"\n",(0,s.jsxs)(t.li,{children:["\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Topic 4.4 practicum task"})," (trace a behaviour incident) produces a six-step analysis. Use it to\nmake the point that the unexpected is the moment when the classroom's culture is most visible."]}),"\n"]}),"\n"]}),"\n",(0,s.jsx)(t.h2,{id:"a-note-on-the-figures",children:"A note on the figures"}),"\n",(0,s.jsx)(t.p,{children:"The unit carries eight figures: two concept-map figures that make a relational structure visible\n(fig-U4-1, fig-U4-3), two flowchart figures that sequence a process (fig-U4-2, fig-U4-4), and four\ntables that compare options against a criterion (fig-U4-5, fig-U4-6, fig-U4-7, fig-U4-8). The\ntables are the ones trainees most often try to read as prose. Before you project any of them, ask\ntrainees to read the column headers first and say what the table is comparing."}),"\n",(0,s.jsx)(t.h2,{id:"assessment-note",children:"Assessment note"}),"\n",(0,s.jsx)(t.p,{children:"The 10/10/5 bank is designed to be used in two passes: the MCQs and RRQs as formative checks at\nthe end of Topics 4.2 and 4.4, and the ERQs as a summative task at the end of the unit. ERQ 5 (the\nintegrative item) is the one that most reliably separates trainees who have understood the unit\nfrom those who have memorised its definitions. If you use only one ERQ, use that one."})]})}function d(e={}){const{wrapper:t}={...(0,o.R)(),...e.components};return t?(0,s.jsx)(t,{...e,children:(0,s.jsx)(u,{...e})}):u(e)}},6606(e,t,n){n.d(t,{A:()=>s});n(6540);var i=n(4848);function s(e){var t=e.label,n=void 0===t?"Print / Save as PDF":t;return(0,i.jsxs)("button",{type:"button",className:"print-handout print-hidden","aria-label":"Print or save this handout as a PDF",onClick:function(){return"undefined"!=typeof window&&window.print()},children:[(0,i.jsx)("span",{"aria-hidden":"true",children:"\ud83d\udda8 "}),n]})}},8453(e,t,n){n.d(t,{R:()=>a,x:()=>r});var i=n(6540);const s={},o=i.createContext(s);function a(e){const t=i.useContext(o);return i.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:a(e.components),i.createElement(o.Provider,{value:t},e.children)}}}]);